	}, "\n")
	var first bytes.Buffer
	if _, err := NormalizeReader(strings.NewReader(input), &first); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 5; i++ {
		var again bytes.Buffer
		if _, err := NormalizeReader(strings.NewReader(input), &again); err != nil {
